style.css:
@-moz-document domain("facebook.com") {
/* Simplify background */
  body, #pagelet_bluebar, #mount_0_0 {
    background-color: #f0f2f5 !important;
    font-family: Arial, Helvetica, sans-serif !important;
  }

  /* Remove Stories and Reels */
  [aria-label="Stories"], [aria-label="Reels"], [aria-label="Rooms"] {
    display: none !important;
  }

  /* Simplify top blue bar */
  #blueBarDOMInspector, #blueBar {
    background-color: #3b5998 !important;
    height: 50px !important;
  }

  /* Remove modern icons and round buttons */
  div[role="button"], a[role="button"] {
    border-radius: 0 !important;
  }

  /* Simplify text colors */
  a, span, div {
    color: #1d2129 !important;
  }

  /* Make posts simpler */
  [data-pagelet^="FeedUnit_"] {
    border: 1px solid #ccc !important;
    background-color: white !important;
    margin-bottom: 10px !important;
    padding: 10px !important;
    border-radius: 0 !important;
  }

  /* Remove shadows and animations */
  *, *::before, *::after {
    box-shadow: none !important;
    transition: none !important;
    animation: none !important;
  }
}
